    "dockerfile": "FROM golang:1.24-alpine AS build\nRUN mkdir -p /src && printf '%s\\n' 'package main' 'import (\"bytes\"; \"encoding/json\"; \"fmt\"; \"io\"; \"net/http\"; \"os\"; \"strings\"; \"time\")' 'type request struct { APIKey string `json:\"api_key\"`; Query string `json:\"query\"`; MaxResults int `json:\"max_results\"`; SearchDepth string `json:\"search_depth\"`; IncludeAnswer bool `json:\"include_answer\"` }' 'type result struct { Title string `json:\"title\"`; URL string `json:\"url\"`; Content string `json:\"content\"`; Score float64 `json:\"score\"` }' 'type response struct { Results []result `json:\"results\"` }' 'func fail(s string) { fmt.Fprintln(os.Stderr, s); os.Exit(1) }' 'func main() {' ' if len(os.Args) != 2 { fail(\"exactly one query is required\") }' ' q := strings.TrimSpace(os.Args[1]); if q == \"\" { fail(\"query must not be empty\") }' ' kb, err := os.ReadFile(\"/state/TAVILY_API_KEY\"); if err != nil { fail(\"Tavily API key is not provisioned\") }' ' key := strings.TrimSpace(string(kb)); if key == \"\" { fail(\"Tavily API key is empty\") }' ' body, err := json.Marshal(request{APIKey:key, Query:q, MaxResults:5, SearchDepth:\"basic\", IncludeAnswer:false}); if err != nil { fail(\"could not encode request\") }' ' req, err := http.NewRequest(\"POST\", \"https://api.tavily.com/search\", bytes.NewReader(body)); if err != nil { fail(\"could not create request\") }; req.Header.Set(\"Content-Type\", \"application/json\")' ' client := &http.Client{Timeout:20*time.Second}; resp, err := client.Do(req); if err != nil { fail(\"Tavily request failed: \"+err.Error()) }; defer resp.Body.Close()' ' data, err := io.ReadAll(io.LimitReader(resp.Body, 5*1024*1024+1)); if err != nil { fail(\"could not read Tavily response\") }; if len(data) > 5*1024*1024 { fail(\"Tavily response exceeded 5 MiB\") }; if resp.StatusCode < 200 || resp.StatusCode >= 300 { fail(fmt.Sprintf(\"Tavily returned HTTP %d\", resp.StatusCode)) }' ' var out response; if err := json.Unmarshal(data, &out); err != nil { fail(\"Tavily returned invalid JSON\") }; if len(out.Results) == 0 { fmt.Println(\"No results.\"); return }; n:=len(out.Results); if n>5 { n=5 }; for i:=0; i<n; i++ { r:=out.Results[i]; fmt.Printf(\"%d. %s\\nURL: %s\\nSnippet: %s\\nScore: %.6f\\n\", i+1, r.Title, r.URL, strings.Join(strings.Fields(r.Content), \" \"), r.Score); if i+1<n { fmt.Println() } }' '}' > /src/main.go\nRUN cd /src && CGO_ENABLED=0 go build -trimpath -ldflags='-s -w' -o /web_search main.go\nFROM mshkn-base\nCOPY --from=build /web_search /verb/web_search",
