   "kind": "verb",
   "log": null,
   "rationale": "Mike requested a verb that reads a supplied URL. This tested verb fetches public HTTP/HTTPS pages, emits readable text for HTML (or textual JSON/XML/plain content), and mitigates SSRF by rejecting private/reserved addresses on every connection and redirect. It accepts no URL credentials, restricts requests to standard web ports, follows at most five redirects, caps downloads at 2 MiB, times out, has no secrets or persistent state, and is restricted to ssh:mike.",
   "recipe_id": "rcp-6b887eba93cc",
   "status": "ready",
   "supersedes": null,
   "title": "Add a safe public web-page reader",
   "verb": {
    "allow": [
     "ssh:mike"
    ],
    "chain": "verb/web_read",
    "description": "Fetch a public HTTP or HTTPS URL and print its readable textual content. Blocks local/private/reserved network destinations and redirects, permits only standard web ports, and caps downloads at 2 MiB.",
    "dockerfile": "FROM golang:1.24-alpine AS build\nRUN printf '%s\\n' 'package main' 'import (' ' \"context\"' ' \"errors\"' ' \"fmt\"' ' \"html\"' ' \"io\"' ' \"net\"' ' \"net/http\"' ' \"net/url\"' ' \"os\"' ' \"regexp\"' ' \"strings\"' ' \"time\"' ')' 'var blocked = mustCIDRs([]string{\"0.0.0.0/8\",\"10.0.0.0/8\",\"100.64.0.0/10\",\"127.0.0.0/8\",\"169.254.0.0/16\",\"172.16.0.0/12\",\"192.0.0.0/24\",\"192.0.2.0/24\",\"192.168.0.0/16\",\"198.18.0.0/15\",\"198.51.100.0/24\",\"203.0.113.0/24\",\"224.0.0.0/4\",\"240.0.0.0/4\",\"::/128\",\"::1/128\",\"fc00::/7\",\"fe80::/10\",\"ff00::/8\",\"2001:db8::/32\"})' 'func mustCIDRs(xs []string) []*net.IPNet { var out []*net.IPNet; for _, s := range xs { _, n, _ := net.ParseCIDR(s); out=append(out,n) }; return out }' 'func public(ip net.IP) bool { if !ip.IsGlobalUnicast() { return false }; for _, n := range blocked { if n.Contains(ip) { return false } }; return true }' 'func dial(ctx context.Context, network, addr string) (net.Conn,error) { host,port,e:=net.SplitHostPort(addr); if e!=nil{return nil,e}; ips,e:=net.DefaultResolver.LookupIP(ctx,\"ip\",host); if e!=nil{return nil,e}; for _,ip:=range ips { if !public(ip) { return nil,errors.New(\"destination resolves to a non-public address\") } }; if len(ips)==0{return nil,errors.New(\"no addresses\")}; return (&net.Dialer{Timeout:10*time.Second}).DialContext(ctx,network,net.JoinHostPort(ips[0].String(),port)) }' 'func validate(raw string) error { u,e:=url.Parse(raw); if e!=nil{return e}; if u.Scheme!=\"http\"&&u.Scheme!=\"https\" {return errors.New(\"only http and https URLs are allowed\")}; if u.Hostname()==\"\"||u.User!=nil{return errors.New(\"URL must have a host and no credentials\")}; p:=u.Port(); if (u.Scheme==\"http\"&&p!=\"\"&&p!=\"80\")||(u.Scheme==\"https\"&&p!=\"\"&&p!=\"443\"){return errors.New(\"only standard web ports are allowed\")}; return nil }' 'var scripts=regexp.MustCompile(`(?is)<(script|style|noscript)[^>]*>.*?</(script|style|noscript)>`)' 'var tags=regexp.MustCompile(`(?s)<[^>]*>`)' 'func readable(s string) string { s=scripts.ReplaceAllString(s,\" \"); s=regexp.MustCompile(`(?i)<br\\\\s*/?>|</(p|div|li|h[1-6]|tr)>`).ReplaceAllString(s,\"\\\\n\"); s=tags.ReplaceAllString(s,\" \"); s=html.UnescapeString(s); var out []string; for _,line:=range strings.Split(s,\"\\\\n\") { if x:=strings.Join(strings.Fields(line),\" \"); x!=\"\" {out=append(out,x)} }; return strings.Join(out,\"\\\\n\") }' 'func main(){ if len(os.Args)!=2 {fmt.Fprintln(os.Stderr,\"usage: web-read URL\");os.Exit(2)}; if e:=validate(os.Args[1]);e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(2)}; tr:=&http.Transport{Proxy:nil,DialContext:dial,TLSHandshakeTimeout:10*time.Second,ResponseHeaderTimeout:15*time.Second}; c:=&http.Client{Transport:tr,Timeout:25*time.Second,CheckRedirect:func(r *http.Request,v []*http.Request) error {if len(v)>=5{return errors.New(\"too many redirects\")};return validate(r.URL.String())}}; r,e:=c.Get(os.Args[1]);if e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)};defer r.Body.Close();if r.StatusCode<200||r.StatusCode>299{fmt.Fprintf(os.Stderr,\"HTTP %s\\\\n\",r.Status);os.Exit(1)}; ct:=strings.ToLower(r.Header.Get(\"Content-Type\"));if !(strings.HasPrefix(ct,\"text/\")||strings.Contains(ct,\"json\")||strings.Contains(ct,\"xml\")){fmt.Fprintln(os.Stderr,\"unsupported content type:\",ct);os.Exit(1)}; b,e:=io.ReadAll(io.LimitReader(r.Body,2*1024*1024+1));if e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)};if len(b)>2*1024*1024{fmt.Fprintln(os.Stderr,\"page exceeds 2 MiB limit\");os.Exit(1)};if strings.Contains(ct,\"html\"){fmt.Println(readable(string(b)))}else{fmt.Print(string(b))}}' > /tmp/main.go\nRUN CGO_ENABLED=0 go build -o /web-read /tmp/main.go\nFROM mshkn-base\nCOPY --from=build /web-read /usr/local/bin/web-read\nRUN chmod 0755 /usr/local/bin/web-read",
