    "dockerfile": "FROM mshkn-base\nRUN mkdir -p /verb && printf '%s\\n' '#!/bin/sh' 'set -eu' 'KEY_FILE=/state/TAVILY_API_KEY' 'if [ ! -s \"$KEY_FILE\" ]; then' '  printf \"%s\\n\" \"{\\\"error\\\":\\\"Tavily API key is not provisioned\\\"}\"' '  exit 1' 'fi' 'key=$(cat \"$KEY_FILE\")' 'request=$(mktemp)' 'response=$(mktemp)' 'trap '\\''rm -f \"$request\" \"$response\"'\\'' EXIT HUP INT TERM' 'QUERY=\"$1\" perl -MJSON::PP -e '\\''my $q=$ENV{QUERY}; die \"invalid query\\n\" if !defined($q) || length($q)<1 || length($q)>1000; print encode_json({query=>$q,search_depth=>\"basic\",max_results=>5,include_answer=>JSON::PP::false,include_raw_content=>JSON::PP::false})'\\'' > \"$request\"' 'code=$(curl --silent --show-error --location --max-redirs 0 --connect-timeout 5 --max-time 20 --max-filesize 5242880 --output \"$response\" --write-out \"%{http_code}\" --request POST --header \"Authorization: Bearer $key\" --header \"Content-Type: application/json\" --data-binary \"@$request\" \"https://api.tavily.com/search\") || {' '  printf \"%s\\n\" \"{\\\"error\\\":\\\"Tavily request failed\\\"}\"' '  exit 1' '}' 'case \"$code\" in 2??) ;; *) printf \"{\\\"error\\\":\\\"Tavily API returned HTTP %s\\\"}\\n\" \"$code\"; exit 1 ;; esac' 'perl -MJSON::PP -0777 -e '\\''eval { $d=decode_json(<STDIN>) }; if ($@ || ref($d) ne \"HASH\" || ref($d->{results}) ne \"ARRAY\") { print \"{\\\"error\\\":\\\"Tavily returned invalid JSON\\\"}\\n\"; exit 1 } @o=(); for $i (@{$d->{results}}[0..($#{$d->{results}}<4?$#{$d->{results}}:4)]) { next unless ref($i) eq \"HASH\"; push @o,{map { $_=>$i->{$_} } qw(title url content score)} } print encode_json({results=>\\@o}),\"\\n\"'\\'' < \"$response\"' > /verb/run.sh\nRUN chmod 0555 /verb/run.sh",
